const columns=['ID','name','skill','status'];
const statuses=['available','busy','inactive'];
const fail=code=>{throw new Error(code)};
const same=(a,b)=>JSON.stringify(a)===JSON.stringify(b);
function authority(p,write=false){if(!p||typeof p.userId!=='string'||!p.userId||p.read!==true)fail('READ_DENIED');if(write&&p.write!==true)fail('WRITE_DENIED');}
const record=r=>r!==null&&typeof r==='object'&&Object.prototype.toString.call(r)==='[object Object]'&&Object.getOwnPropertySymbols(r).length===0;
function copyReceipt(r){if(!record(r)||Object.keys(r).length!==4||!['requestId','fingerprint','row','principal'].every(k=>Object.hasOwn(r,k))||['requestId','fingerprint','principal'].some(k=>typeof r[k]!=='string'||!r[k]))fail('INVALID_RECEIPT');schema([r.row]);return {requestId:r.requestId,fingerprint:r.fingerprint,row:{...r.row},principal:r.principal};}
function schema(rows){if(!Array.isArray(rows))fail('INVALID_ROWS');const seen=new Set();for(const r of rows){if(!record(r)||columns.some(c=>!Object.hasOwn(r,c)||typeof r[c]!=='string'||!r[c].trim())||Object.getOwnPropertyNames(r).some(c=>!columns.includes(c))||columns.some(c=>!Object.hasOwn(Object.getOwnPropertyDescriptor(r,c),'value')||Object.getOwnPropertyDescriptor(r,c).enumerable!==true)||!statuses.includes(r.status)||seen.has(r.ID))fail('INVALID_ROWS');seen.add(r.ID);}}
function changes(patch){if(!patch||Array.isArray(patch)||typeof patch!=='object'||!Object.keys(patch).length||Object.keys(patch).some(k=>!['skill','status'].includes(k)||typeof patch[k]!=='string'||!patch[k].trim()||patch[k].length>200)||(Object.hasOwn(patch,'status')&&!statuses.includes(patch.status)))fail('INVALID_UPDATE');}
function lookup(rows,q,p){authority(p);schema(rows);if(!q||!columns.includes(q.query_column)||typeof q.query_value!=='string'||!q.query_value.trim()||q.query_value.length>200)fail('INVALID_QUERY');const value=q.query_value.trim().toLowerCase();return rows.filter(r=>q.query_column==='ID'?r.ID===q.query_value:r[q.query_column].toLowerCase().includes(value)).map(r=>({...r}));}
function preview(rows,q,patch,p){authority(p,true);changes(patch);const matches=lookup(rows,q,p);if(!matches.length)fail('NOT_FOUND');if(matches.length!==1)fail('AMBIGUOUS');const before=matches[0];return {version:1,principal:p.userId,rowId:before.ID,before,after:{...before,...patch},patch:{...patch}};}
function createState(rows){schema(rows);return {rows:rows.map(r=>({...r})),receipts:[]};}
function commit(state,plan,p,requestId,listenerReady){authority(p,true);if(listenerReady!==true)fail('LISTENER_UNAVAILABLE');if(typeof requestId!=='string'||!requestId.trim()||requestId.length>100)fail('INVALID_REQUEST');if(!plan||plan.version!==1||plan.principal!==p.userId)fail('PRINCIPAL_MISMATCH');changes(plan.patch);if(!plan.before||!plan.after||plan.rowId!==plan.before.ID||plan.rowId!==plan.after.ID||!same(plan.after,{...plan.before,...plan.patch}))fail('INVALID_PREVIEW');schema([plan.before]);schema([plan.after]);schema(state.rows);const fingerprint=JSON.stringify({plan,userId:p.userId});const old=state.receipts.find(r=>r.requestId===requestId);if(old){if(old.fingerprint!==fingerprint)fail('REQUEST_CONFLICT');return copyReceipt(old);}
const index=state.rows.findIndex(r=>r.ID===plan.rowId);if(index<0||!same(state.rows[index],plan.before))fail('STALE_PREVIEW');state.rows[index]={...plan.after};const receipt={requestId,fingerprint,row:{...plan.after},principal:p.userId};state.receipts.push(receipt);return copyReceipt(receipt);}

